const HEART_MATRIX = [
  "01100110",
  "11111111",
  "11111111",
  "11111111",
  "01111110",
  "00111100",
  "00011000"
];
const STAR_MATRIX = [
  "00100",
  "01110",
  "11111",
  "01110",
  "00100"
];
const MOON_MATRIX = [
  "00111100",
  "01111100",
  "11111100",
  "11111000",
  "11111000",
  "11111100",
  "01111100",
  "00111100"
];

function pixelArt(matrix, size, color){
  const w = matrix[0].length, h = matrix.length;
  const wrap = document.createElement('div');
  wrap.style.width = (w*size)+'px';
  wrap.style.height = (h*size)+'px';
  wrap.style.position = 'relative';
  wrap.style.flexShrink = '0';
  wrap.style.display = 'inline-block';
  const px = document.createElement('div');
  px.style.position = 'absolute';
  px.style.top = '0'; px.style.left = '0';
  px.style.width = size+'px';
  px.style.height = size+'px';
  const shadows = [];
  matrix.forEach((row,y)=>{
    [...row].forEach((c,x)=>{
      if(c==='1') shadows.push(`${x*size}px ${y*size}px 0 0 ${color}`);
    });
  });
  px.style.boxShadow = shadows.join(',');
  wrap.appendChild(px);
  return wrap;
}

