(function buildCake(){
  const holder = document.getElementById('cake-holder');
  const wrap = document.createElement('div');
  wrap.style.display = 'inline-flex';
  wrap.style.flexDirection = 'column';
  wrap.style.alignItems = 'center';
  const flame = document.createElement('div');
  flame.style.width = '10px'; flame.style.height = '16px';
  flame.style.background = 'linear-gradient(#ffe066, #ff8a3d)';
  flame.style.margin = '0 auto 2px auto';
  flame.style.animation = 'flicker 1s ease-in-out infinite';
  const candle = document.createElement('div');
  candle.style.width = '6px'; candle.style.height = '18px';
  candle.style.background = '#fff9dc';
  candle.style.margin = '0 auto';
  const tier1 = document.createElement('div');
  tier1.style.width = '160px'; tier1.style.height = '34px';
  tier1.style.background = '#ffd1de';
  tier1.style.border = '4px solid var(--dark)';
  tier1.style.marginTop = '6px';
  const tier2 = document.createElement('div');
  tier2.style.width = '200px'; tier2.style.height = '40px';
  tier2.style.background = '#ff9fc0';
  tier2.style.border = '4px solid var(--dark)';
  wrap.appendChild(flame);
  wrap.appendChild(candle);
  wrap.appendChild(tier1);
  wrap.appendChild(tier2);
  holder.appendChild(wrap);
  const fs = document.createElement('style');
  fs.textContent = '@keyframes flicker{0%,100%{transform:scaleY(1) translateX(0);}50%{transform:scaleY(.85) translateX(1px);}}';
  document.head.appendChild(fs);
})();

